{
  "summary": "Test for intermittent infotainment malfunctions by running a long power-cycling test, because the touchscreen and stored settings randomly fail.",
  "rationale": "The narrative reports intermittent electrical behavior: the infotainment system randomly goes haywire, the touchscreen becomes unusable, and app icons, connected phones, and radio favorites are deleted or moved. The rulebook matches the condition \"intermittent\" to the Long-run power cycling test, which is intended to reproduce faults that appear after repeated wake and sleep cycles.",
  "group": "electrical_general",
  "symptoms": [
    "infotainment system randomly goes haywire",
    "touchscreen cannot be used",
    "app icons are randomly deleted",
    "connected phones are deleted",
    "radio favorites are deleted",
    "app icons are moved around"
  ],
  "conditions": [
    "intermittent"
  ],
  "fault_codes": [],
  "safety_relevant": false,
  "targeted": true,
  "test_name": "Long-run power cycling test",
  "clues": [
    {
      "kind": "symptom",
      "quote": "infotainment system will just randomly start going haywire"
    },
    {
      "kind": "symptom",
      "quote": "you cannot use the touchscreen"
    },
    {
      "kind": "symptom",
      "quote": "It will try to randomly delete app icons such as the camera"
    },
    {
      "kind": "symptom",
      "quote": "it will try to delete connected phones"
    },
    {
      "kind": "symptom",
      "quote": "it will try to delete radio favorites"
    },
    {
      "kind": "symptom",
      "quote": "it will move app icons all around"
    },
    {
      "kind": "condition",
      "quote": "randomly"
    }
  ]
}

